46	/****************************************************************************
47	 * Name: free_delaylist
48	 *
49	 * Description:
50	 *  Free the memory in delay list either added because of mm_lock failed or
51	 *  added because of CONFIG_MM_FREE_DELAYCOUNT_MAX.
52	 *  Set force to true to free all the memory in delay list immediately, set
53	 *  to false will only free delaylist when time is up if
54	 *  CONFIG_MM_FREE_DELAYCOUNT_MAX is enabled.
55	 *
56	 *  Return true if there is memory freed.
57	 *
58	 ****************************************************************************/
59	
60	static bool free_delaylist(FAR struct mm_heap_s *heap, bool force)
61	{
62	  bool ret = false;
63	#if defined(CONFIG_BUILD_FLAT) || defined(__KERNEL__)
64	  FAR struct mm_delayhead_s *delay = get_delayhead(heap);
65	  FAR struct mm_delaynode_s *tmp;
66	  irqstate_t flags;
67	  bool bypass;
68	
69	  /* Move the delay list to local */
70	
71	  flags = up_irq_save();
72	  bypass = kasan_bypass(true);
73	
74	  tmp = delay->head;
75	
76	#  if CONFIG_MM_FREE_DELAYCOUNT_MAX > 0
77	  if (tmp == NULL || (!force &&
78	      delay->delaycount < CONFIG_MM_FREE_DELAYCOUNT_MAX))
79	    {
80	      up_irq_restore(flags);
81	      return false;
82	    }
83	
84	  delay->delaycount = 0;
85	#  endif
86	
87	  delay->head = NULL;
88	
89	  kasan_bypass(bypass);
90	  up_irq_restore(flags);
91	
92	  /* Test if the delayed is empty */
93	
94	  ret = !!tmp;
95	
96	  while (tmp)
97	    {
98	      FAR void *address;
99	
100	      /* Get the first delayed deallocation */
101	
102	      address = tmp;
103	      tmp = tmp->flink;
104	
105	      /* The address should always be non-NULL since that was checked in the
106	       * 'while' condition above.
107	       */
108	
109	      mm_forcefree(heap, address);
110	    }
111	
112	#endif
113	  return ret;
114	}
