165	/****************************************************************************
166	 * Name: mm_malloc
167	 *
168	 * Description:
169	 *  Find the smallest chunk that satisfies the request. Take the memory from
170	 *  that chunk, save the remaining, smaller chunk (if any).
171	 *
172	 *  8-byte alignment of the allocated data is assured.
173	 *
174	 ****************************************************************************/
175	
176	FAR void *mm_malloc(FAR struct mm_heap_s *heap, size_t size)
177	{
178	  FAR struct mm_freenode_s *node;
179	  size_t alignsize;
180	  size_t nodesize;
181	  FAR void *ret = NULL;
182	  bool bypass;
183	  int ndx;
184	
185	  /* Free the delay list first */
186	
187	  free_delaylist(heap, false);
188	
189	#ifdef CONFIG_MM_HEAP_MEMPOOL
190	  if (heap->mm_mpool)
191	    {
192	      ret = mempool_multiple_alloc(heap->mm_mpool, size);
193	      if (ret != NULL)
194	        {
195	          return ret;
196	        }
197	    }
198	#endif
199	
200	  /* Adjust the size to account for (1) the size of the allocated node and
201	   * (2) to make sure that it is aligned with MM_ALIGN and its size is at
202	   * least MM_MIN_CHUNK.
203	   */
204	
205	  if (size < MM_MIN_CHUNK - MM_ALLOCNODE_OVERHEAD)
206	    {
207	      size = MM_MIN_CHUNK - MM_ALLOCNODE_OVERHEAD;
208	    }
209	
210	  alignsize = MM_ALIGN_UP(size + MM_ALLOCNODE_OVERHEAD);
211	  if (alignsize < size)
212	    {
213	      /* There must have been an integer overflow */
214	
215	      return NULL;
216	    }
217	
218	  DEBUGASSERT(alignsize >= MM_ALIGN);
219	
220	  /* We need to hold the MM mutex while we muck with the nodelist. */
221	
222	  DEBUGVERIFY(nxrmutex_lock(&heap->mm_lock));
223	  bypass = kasan_bypass(true);
224	
225	  /* Convert the request size into a nodelist index */
226	
227	  ndx = mm_size2ndx(alignsize);
228	
229	  /* Search for a large enough chunk in the list of nodes. This list is
230	   * ordered by size, but will have occasional zero sized nodes as we visit
231	   * other mm_nodelist[] entries.
232	   */
233	
234	  for (node = heap->mm_nodelist[ndx].flink; node; node = node->flink)
235	    {
236	      DEBUGASSERT(node->blink->flink == node);
237	      nodesize = MM_SIZEOF_NODE(node);
238	      if (nodesize >= alignsize)
239	        {
240	          break;
241	        }
242	    }
243	
244	  /* If we found a node with non-zero size, then this is one to use. Since
245	   * the list is ordered, we know that it must be the best fitting chunk
246	   * available.
247	   */
248	
249	  if (node)
250	    {
251	      FAR struct mm_freenode_s *remainder;
252	      FAR struct mm_freenode_s *next;
253	      size_t remaining;
254	
255	      /* Remove the node.  There must be a predecessor, but there may not be
256	       * a successor node.
257	       */
258	
259	      DEBUGASSERT(node->blink);
260	      node->blink->flink = node->flink;
261	      if (node->flink)
262	        {
263	          node->flink->blink = node->blink;
264	        }
265	
266	      /* Get a pointer to the next node in physical memory */
267	
268	      next = (FAR struct mm_freenode_s *)(((FAR char *)node) + nodesize);
269	
270	      /* Node next must be alloced, otherwise it should be merged.
271	       * Its prenode(the founded node) must be free and preceding should
272	       * match with nodesize.
273	       */
274	
275	      DEBUGASSERT(MM_NODE_IS_ALLOC(next) && MM_PREVNODE_IS_FREE(next) &&
276	                  next->preceding == nodesize);
277	
278	      /* Check if we have to split the free node into one of the allocated
279	       * size and another smaller freenode.  In some cases, the remaining
280	       * bytes can be smaller (they may be MM_SIZEOF_ALLOCNODE).  In that
281	       * case, we will just carry the few wasted bytes at the end of the
282	       * allocation.
283	       */
284	
285	      remaining = nodesize - alignsize;
286	      if (remaining >= MM_MIN_CHUNK)
287	        {
288	          /* Create the remainder node */
289	
290	          remainder = (FAR struct mm_freenode_s *)
291	            (((FAR char *)node) + alignsize);
292	
293	          remainder->size = remaining;
294	
295	          /* Adjust the size of the node under consideration */
296	
297	          node->size = alignsize | (node->size & MM_MASK_BIT);
298	
299	          /* Adjust the 'preceding' size of the (old) next node. */
300	
301	          next->preceding = remaining;
302	
303	          /* Add the remainder back into the nodelist */
304	
305	          mm_addfreechunk(heap, remainder);
306	        }
307	      else
308	        {
309	          /* Previous physical memory node is alloced, so clear the previous
310	           * free bit in next->size.
311	           */
312	
313	          next->size &= ~MM_PREVFREE_BIT;
314	        }
315	
316	      /* Update heap statistics */
317	
318	      nodesize = MM_SIZEOF_NODE(node);
319	      heap->mm_curused += nodesize;
320	      if (heap->mm_curused > heap->mm_maxused)
321	        {
322	          heap->mm_maxused = heap->mm_curused;
323	        }
324	
325	      /* Handle the case of an exact size match */
326	
327	      node->size |= MM_ALLOC_BIT;
328	      ret = (FAR void *)((FAR char *)node + MM_SIZEOF_ALLOCNODE);
329	    }
330	
331	  DEBUGASSERT(ret == NULL || mm_heapmember(heap, ret));
332	
333	  if (ret)
334	    {
335	      sched_note_heap(NOTE_HEAP_ALLOC, heap, ret, nodesize,
336	                      heap->mm_curused);
337	    }
338	
339	  kasan_bypass(bypass);
340	  DEBUGVERIFY(nxrmutex_unlock(&heap->mm_lock));
341	
342	  if (ret)
343	    {
344	      MM_RECORD(heap, node);
345	      ret = kasan_unpoison(ret, nodesize - MM_ALLOCNODE_OVERHEAD);
346	#ifdef CONFIG_MM_FILL_ALLOCATIONS
347	      memset(ret, MM_ALLOC_MAGIC, alignsize - MM_ALLOCNODE_OVERHEAD);
348	#endif
349	#ifdef CONFIG_DEBUG_MM
350	      minfo("Allocated %p, size %zu\n", ret, alignsize);
351	#endif
352	    }
353	
354	#if CONFIG_MM_FREE_DELAYCOUNT_MAX > 0
355	  /* Try again after free delay list */
356	
357	  else if (free_delaylist(heap, true))
358	    {
359	      return mm_malloc(heap, size);
360	    }
361	#endif
362	
363	  else if (MM_INTERNAL_HEAP(heap))
364	    {
365	#ifdef CONFIG_MM_DUMP_ON_FAILURE
366	      struct mallinfo minfo;
367	#  ifdef CONFIG_MM_DUMP_DETAILS_ON_FAILURE
368	      struct mm_memdump_s dump =
369	      {
370	        PID_MM_ALLOC,
371	#    ifdef CONFIG_MM_RECORD_SEQNO
372	        0, ULONG_MAX
373	#    endif
374	      };
375	#  endif
376	#endif
377	
378	#ifdef CONFIG_DEBUG_MM
379	      mwarn("WARNING: Allocation failed, size %zu\n", alignsize);
380	#endif
381	#ifdef CONFIG_MM_DUMP_ON_FAILURE
382	      minfo = mm_mallinfo(heap);
383	      mwarn("Total:%d, used:%d, free:%d, largest:%d, nused:%d, nfree:%d\n",
384	            minfo.arena, minfo.uordblks, minfo.fordblks,
385	            minfo.mxordblk, minfo.aordblks, minfo.ordblks);
386	
387	      mm_trace_diag(DIAG_MM_ALLOC_FAIL,
388	                    "size:%zu, total:%d, used:%d, free:%d, "
389	                    "largest:%d, nused:%d, nfree:%d",
390	                    alignsize, minfo.arena, minfo.uordblks, minfo.fordblks,
391	                    minfo.mxordblk, minfo.aordblks, minfo.ordblks);
392	#  ifdef CONFIG_MM_RECORD_PID
393	      nxsched_foreach(mm_dump_handler, heap);
394	      mm_dump_handler(NULL, heap);
395	#  endif
396	#  ifdef CONFIG_MM_HEAP_MEMPOOL
397	      mwarn("%11s%9s%9s%9s%9s%9s\n",
398	            "bsize", "total", "nused",
399	            "nfree", "nifree", "nwaiter");
400	      mempool_multiple_foreach(heap->mm_mpool,
401	                               mm_mempool_dump_handle, NULL);
402	#  endif
403	#  ifdef CONFIG_MM_DUMP_DETAILS_ON_FAILURE
404	      mm_memdump(heap, &dump);
405	      mwarn("Dump leak memory(thread exit, but memory not free):\n");
406	      dump.pid = PID_MM_LEAK;
407	      mm_memdump(heap, &dump);
408	#    ifdef CONFIG_MM_HEAP_MEMPOOL
409	      mwarn("Dump block used by mempool expand/trunk:\n");
410	      dump.pid = PID_MM_MEMPOOL;
411	      mm_memdump(heap, &dump);
412	#    endif
413	      mwarn("Dump allocated orphan nodes. (neighbor of free nodes):\n");
414	      dump.pid = PID_MM_ORPHAN;
415	      mm_memdump(heap, &dump);
416	#  endif
417	#else
418	    mm_trace_diag(DIAG_MM_ALLOC_FAIL, "size:%zu", alignsize);
419	#endif
420	#ifdef CONFIG_MM_PANIC_ON_FAILURE
421	      PANIC();
422	#endif
423	    }
424	
425	  DEBUGASSERT(ret == NULL || ((uintptr_t)ret) % MM_ALIGN == 0);
426	  return ret;
427	}
