 *  Set force to true to free all the memory in delay list immediately, set
 *  to false will only free delaylist when time is up if
 *  CONFIG_MM_FREE_DELAYCOUNT_MAX is enabled.
 *
 *  Return true if there is memory freed.
 *
 ****************************************************************************/

static bool free_delaylist(FAR struct mm_heap_s *heap, bool force)
{
  bool ret = false;
#if defined(CONFIG_BUILD_FLAT) || defined(__KERNEL__)
  FAR struct mm_delayhead_s *delay = get_delayhead(heap);
  FAR struct mm_delaynode_s *tmp;
  irqstate_t flags;
  bool bypass;

  /* Move the delay list to local */

  flags = up_irq_save();
  bypass = kasan_bypass(true);

  tmp = delay->head;

#  if CONFIG_MM_FREE_DELAYCOUNT_MAX > 0
  if (tmp == NULL || (!force &&
      delay->delaycount < CONFIG_MM_FREE_DELAYCOUNT_MAX))
    {
      up_irq_restore(flags);
      return false;
    }

  delay->delaycount = 0;
#  endif

  delay->head = NULL;

  kasan_bypass(bypass);
  up_irq_restore(flags);

  /* Test if the delayed is empty */

  ret = !!tmp;

  while (tmp)
    {
      FAR void *address;

      /* Get the first delayed deallocation */

      address = tmp;
      tmp = tmp->flink;

      /* The address should always be non-NULL since that was checked in the
       * 'while' condition above.
       */

      mm_forcefree(heap, address);
    }

#endif
  return ret;
}

